capture_with_status "GET" "$BASE_URL/credit-card-years" ""
YEARS_COUNT=$(echo "$LAST_BODY" | jq -r '.items | length' 2>/dev/null)
if [ "$YEARS_COUNT" = "10" ]; then
    echo -e "  ${GREEN}✅ PASSED${NC} (10 years)"
