else
    echo -e "  ${RED}❌ FAILED${NC} (Expected 10 year entries, got: $YEARS_COUNT)"
    FAILED=$((FAILED + 1))
    FAILED_TESTS+=("Test 62: Credit-card years count [BR-REF-API-003] - Expected 10, got $YEARS_COUNT")
