# --- BR-REF-SEED-001: Seeded only when DB empty (guard) — effect: DB is populated, not empty ---
# State-model effect: after bootstrap the aggregate is Seeded, so reference data exists.
assert_status_and_capture 66 "Post-seed: languages exist (Seeded state, not Empty)" "BR-REF-SEED-001" \
    "GET" "$BASE_URL/languages" "" "200"
TOTAL=$((TOTAL + 1))
echo -e "\n${BLUE}Test 67: Post-seed language count > 0 (guard latched to Seeded)${NC}"
echo -e "  Rule: BR-REF-SEED-001 | Expected: items length >= 1"
capture_with_status "GET" "$BASE_URL/languages" ""
LANG_COUNT=$(echo "$LAST_BODY" | jq -r '.items | length' 2>/dev/null)
if [ -n "$LANG_COUNT" ] && [ "$LANG_COUNT" -ge 1 ] 2>/dev/null; then
    echo -e "  ${GREEN}✅ PASSED${NC} ($LANG_COUNT languages)"
    PASSED=$((PASSED + 1))
else
    echo -e "  ${RED}❌ FAILED${NC} (Expected >=1 language after seed, got: $LANG_COUNT)"
    FAILED=$((FAILED + 1))
    FAILED_TESTS+=("Test 67: Post-seed language count [BR-REF-SEED-001] - Expected >=1, got $LANG_COUNT")
fi

# --- BR-REF-SEED-002: Full seed is one ordered, all-or-nothing transaction ---
# Atomic-order effect: dependent data present together — countries (need languages) AND their
# zones (need countries) AND currencies all resolved => the transaction committed as a whole.
assert_status 68 "Atomic seed: seeded country resolvable (languages+countries committed)" "BR-REF-SEED-002" \
    "GET" "$BASE_URL/countries/CA?language=en" "" "200"
assert_json_field 69 "Atomic seed: seeded country's zones present (countries+zones committed)" "BR-REF-SEED-002" \
    "GET" "$BASE_URL/countries/CA/zones?language=en" "" '"items":'
assert_json_field 70 "Atomic seed: currencies present (currencies committed in same tx)" "BR-REF-SEED-002" \
    "GET" "$BASE_URL/currencies" "" '"items":'

# --- BR-REF-SEED-003: Out-of-the-box languages are English and French ---
assert_json_field 71 "Seed effect: English language present" "BR-REF-SEED-003" \
    "GET" "$BASE_URL/languages/en" "" '"code":"en"'
assert_json_field 72 "Seed effect: French language present" "BR-REF-SEED-003" \
    "GET" "$BASE_URL/languages/fr" "" '"code":"fr"'

