assert_status 73 "Seed effect: catalog country (CA) was created" "BR-REF-SEED-004a" \
    "GET" "$BASE_URL/countries/CA?language=en" "" "200"
assert_json_field 74 "Seed effect: created country has a localized name in a configured language" "BR-REF-SEED-004a" \
    "GET" "$BASE_URL/countries/CA?language=en" "" '"name":'

# --- BR-REF-SEED-004: Zones seeded from country/language catalog ---
