assert_json_field 76 "Seed effect: zone linked to its country via country_iso_code" "BR-REF-SEED-004" \
    "GET" "$BASE_URL/zones/QC" "" '"country_iso_code":"CA"'

# --- BR-REF-SEED-005: Currencies seeded from catalog (platform-rejected codes skipped) ---
